(CASE WHEN {x} IS NULL OR {y} IS NULL THEN CAST(NULL AS DOUBLE PRECISION) WHEN {x} = 'NaN' OR {y} = 'NaN' OR {y} = 0 OR abs({x}) = 'Infinity' THEN CAST('NaN' AS DOUBLE PRECISION) WHEN abs({y}) = 'Infinity' OR {x} = 0 OR abs({x}) < abs({y}) THEN {x} ELSE sign({x}) * CAST(round(mod((CAST(CAST('x' || encode(float8send(abs({x})), 'hex') AS BIT(64)) AS BIGINT) - (greatest(CAST(CAST('x' || encode(float8send(abs({x})), 'hex') AS BIT(64)) AS BIGINT) >> 52, 1) - 1) * 4503599627370496) * power(CAST(2 AS NUMERIC), greatest(CAST(CAST('x' || encode(float8send(abs({x})), 'hex') AS BIT(64)) AS BIGINT) >> 52, 1) - greatest(CAST(CAST('x' || encode(float8send(abs({y})), 'hex') AS BIT(64)) AS BIGINT) >> 52, 1)), (CAST(CAST('x' || encode(float8send(abs({y})), 'hex') AS BIT(64)) AS BIGINT) - (greatest(CAST(CAST('x' || encode(float8send(abs({y})), 'hex') AS BIT(64)) AS BIGINT) >> 52, 1) - 1) * 4503599627370496)) * power(CAST(2 AS NUMERIC), greatest(CAST(CAST('x' || encode(float8send(abs({y})), 'hex') AS BIT(64)) AS BIGINT) >> 52, 1)), 1000) / power(CAST(2 AS NUMERIC), 1075) AS DOUBLE PRECISION) END)